# Helper function to compute the answer independently
def is_prime_helper(n):
    def check_divisor(d):
        return n % d != 0

    divisors = [d for d in range(2, n + 1) if check_divisor(d)]

    return len(divisors) == 2 and divisors[0] == 1 and divisors[1] == n
